#include <Snooker/AI/BasicScoringAI.h>
#include <fstream>
#include <iterator>
#include <iostream>
#define CHECK(x) do{if(!(x)){std::cerr<<"FAIL basic AI "<<__LINE__<<": "<<#x<<"; "<<error<<'\n';return 1;}}while(false)
std::string Read(const char*p){std::ifstream f(p);return {std::istreambuf_iterator<char>(f),{}};}
int main(int argc,char**argv){using namespace Snooker;std::string error;CHECK(argc==2);PhysicsBundle bundle;CHECK(PhysicsBundle::Deserialize(Read(argv[1]),bundle,&error));TableGeometry g;CHECK(GenerateTableGeometry(bundle.Table,bundle.Cushions,bundle.Pockets,bundle.Geometry,g,&error));BallState cue;cue.Id=1;cue.PositionMeters={0,-.6,cue.RadiusMeters};auto red=cue;red.Id=2;red.PositionMeters={0,-.78,red.RadiusMeters};PhysicsClock c;auto p=PhysicsSnapshot::Capture(c,{cue,red},bundle.Version,ESnapshotPhase::BeforeShot);BallDefinition cd;cd.Id=1;cd.Type=EBallType::Cue;cd.InitialPositionMeters=cue.PositionMeters;auto rd=cd;rd.Id=2;rd.Type=EBallType::Red;rd.InitialPositionMeters=red.PositionMeters;MatchState m;auto q=CreateAIStateQuery(m,p,{cd,rd},bundle.Cue,&error);CHECK(q);const auto hash=q->StateHash();BasicAIResult result;CHECK(ChooseBasicScoringShot(*q,bundle,g,result,&error));CHECK(result.Candidate.TargetBall==2&&result.Generated==18&&result.Evaluated>0);CHECK(result.Evaluation.LegalPotted>0&&!result.Evaluation.CueBallPotted&&result.Evaluation.Score>0);ShotInput input;CHECK(result.Candidate.ToShotInput(*q,input,&error));CHECK(input.ValidateFor(bundle.Cue,cue,&error));CHECK(q->StateHash()==hash);PhysicsShotRecord replay;CHECK(ReplayShot(result.Evaluation.Record,replay,&error));CHECK(replay.Serialize()==result.Evaluation.Record.Serialize());std::cout<<"PASS basic AI generated/evaluated real candidates and selected a legal scoring shot\n";}
